// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver.code.length == 0); // plain EOA so transfer succeeds
        vm.assume(uint256(uint160(receiver)) > 100); // avoid precompiles/system addresses
        amount = bound(amount, 1, 1e30);
        vm.deal(address(c), amount);
        uint256 before = receiver.balance;
        vm.prank(address(this)); // setUp ran with this contract as sender, so owner == address(this)
        c.sendTo(receiver, amount);
        assertEq(receiver.balance - before, amount, "receiver must gain exactly amount wei");
    }
}
